import { useState } from 'react';
import { FileText, Loader2 } from 'lucide-react';
import { format, startOfMonth } from 'date-fns';

import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/shared/ui/dialog';
import { toast } from '@/shared/hooks/use-toast';
import { supabase } from '@/integrations/supabase/client';
import { wideError } from '@/shared/lib/telemetry/wide-events';
import {
  generateProducaoDiariaPdf,
  type ProducaoEntry,
} from './pdf/ProducaoDiariaPdfGenerator';

interface DailyProductionRow {
  date: string;
  product_name: string;
  quantity: number;
}

const PAGE_SIZE = 1000;

const today = (): string => format(new Date(), 'yyyy-MM-dd');
const firstOfMonth = (): string => format(startOfMonth(new Date()), 'yyyy-MM-dd');

/**
 * Botão de cabeçalho que gera o relatório PDF de Produção Diária.
 *
 * Abre um dialog com seletor de período (intervalo de datas) e produz um PDF
 * de alto nível (totais por produto) consolidado de TODAS as lojas. Não filtra
 * por loja — é sempre consolidado.
 */
export function ProducaoDiariaReportButton(): JSX.Element {
  const [open, setOpen] = useState(false);
  const [dateStart, setDateStart] = useState<string>(firstOfMonth());
  const [dateEnd, setDateEnd] = useState<string>(today());
  const [loading, setLoading] = useState(false);

  /**
   * Busca TODAS as linhas do período paginando de PAGE_SIZE em PAGE_SIZE.
   * O Supabase trunca em 1000 linhas por padrão; sem paginar, períodos longos
   * (ex.: trimestre) subestimam os totais silenciosamente.
   */
  const fetchAllRows = async (): Promise<DailyProductionRow[]> => {
    const all: DailyProductionRow[] = [];
    let offset = 0;

    for (;;) {
      const { data, error } = await supabase
        .from('daily_production')
        .select('date, product_name, quantity')
        .gte('date', dateStart)
        .lte('date', dateEnd)
        .order('date')
        .range(offset, offset + PAGE_SIZE - 1);

      if (error) throw error;

      const page = (data ?? []) as DailyProductionRow[];
      all.push(...page);

      if (page.length < PAGE_SIZE) break;
      offset += PAGE_SIZE;
    }

    return all;
  };

  const handleGenerate = async (): Promise<void> => {
    if (dateEnd < dateStart) {
      toast({
        title: 'Período inválido',
        description: 'A data final deve ser igual ou posterior à data inicial.',
        variant: 'destructive',
      });
      return;
    }

    setLoading(true);
    try {
      const rows = await fetchAllRows();

      if (rows.length === 0) {
        toast({
          title: 'Sem produção no período',
          description: 'Não há lançamentos de produção no intervalo selecionado.',
        });
        return;
      }

      const entries: ProducaoEntry[] = rows.map((r) => ({
        date: r.date,
        product_name: r.product_name,
        quantity: Number(r.quantity) || 0,
      }));

      await generateProducaoDiariaPdf({ entries, dateStart, dateEnd });

      toast({
        title: 'Relatório gerado',
        description: 'O PDF de produção diária foi baixado com sucesso.',
      });
      setOpen(false);
    } catch (err) {
      wideError(
        'producao_diaria.pdf_report_failed',
        'Falha ao gerar relatório PDF de produção diária',
        {
          attributes: {
            'error.message': String(err),
            'operation.name': 'generateProducaoDiariaPdf',
            'report.date_start': dateStart,
            'report.date_end': dateEnd,
          },
        },
      );
      toast({
        title: 'Erro ao gerar relatório',
        description: 'Não foi possível gerar o PDF. Tente novamente.',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button
          variant="outline"
          className="h-10 rounded-full border-[#57715B]/20 bg-[#E6DCCF]/40 px-3 text-[#57715B] hover:bg-[#57715B]/10 dark:border-white/10 dark:bg-white/10 dark:text-[#8FA893] transition-all hover:scale-105"
        >
          <FileText className="h-4 w-4" />
          <span className="hidden sm:inline">Relatório PDF</span>
          <span className="sr-only sm:hidden">Relatório PDF</span>
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="text-[#57715B] dark:text-[#E6DCCF]">
            Relatório de Produção Diária
          </DialogTitle>
          <DialogDescription>
            Gere um PDF consolidado de todas as lojas, com totais por produto no
            período escolhido.
          </DialogDescription>
        </DialogHeader>

        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          <div className="space-y-1.5">
            <label
              htmlFor="producao-pdf-inicio"
              className="text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF]"
            >
              Data inicial
            </label>
            <Input
              id="producao-pdf-inicio"
              data-mia-field="producao_relatorio_data_inicial"
              type="date"
              value={dateStart}
              max={dateEnd}
              onChange={(e) => setDateStart(e.target.value)}
            />
          </div>
          <div className="space-y-1.5">
            <label
              htmlFor="producao-pdf-fim"
              className="text-sm font-medium text-[#2D362E] dark:text-[#E6DCCF]"
            >
              Data final
            </label>
            <Input
              id="producao-pdf-fim"
              data-mia-field="producao_relatorio_data_final"
              type="date"
              value={dateEnd}
              min={dateStart}
              onChange={(e) => setDateEnd(e.target.value)}
            />
          </div>
        </div>

        <DialogFooter>
          <Button
            onClick={handleGenerate}
            disabled={loading}
            data-mia-action="producao_gerar_relatorio_pdf"
            className="bg-[#57715B] text-white hover:bg-[#57715B]/90"
          >
            {loading ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" />
                Gerando...
              </>
            ) : (
              <>
                <FileText className="h-4 w-4" />
                Gerar
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export default ProducaoDiariaReportButton;

