// TEMP: ferramenta temporária de padronização de nomes de Produção Diária — remover após uso (jun/2026).

import { useState, useEffect, useCallback, useMemo } from 'react';
import { Tags, Check, Loader2, Search, AlertCircle } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Badge } from '@/shared/ui/badge';
import {
  Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger,
} from '@/shared/ui/dialog';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from '@/shared/ui/alert-dialog';
import { toast } from '@/shared/hooks/use-toast';
import { supabase } from '@/integrations/supabase/client';
import { useQueryClient } from '@tanstack/react-query';

interface DailyProductionItem {
  product_name: string;
}

interface ProductCount {
  name: string;
  count: number;
}

interface FuseCandidate {
  nameA: string; // Old name
  nameB: string; // New name (existing)
  countA: number; // Count of old name
  countB: number; // Count of new name (if exists)
}

export function PadronizarNomesProducaoButton() {
  const [open, setOpen] = useState<boolean>(false);
  const [items, setItems] = useState<ProductCount[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [fetchError, setFetchError] = useState<string | null>(null);
  const [editMap, setEditMap] = useState<Map<string, string>>(new Map());
  const [savingSet, setSavingSet] = useState<Set<string>>(new Set());
  const [search, setSearch] = useState<string>('');
  const [fuseCandidate, setFuseCandidate] = useState<FuseCandidate | null>(null);

  const queryClient = useQueryClient();

  const normalizeAndLowercase = useCallback((text: string): string => {
    return text.normalize('NFC').toLowerCase();
  }, []);

  // Function to fetch and aggregate product names
  const fetchProductNames = useCallback(async () => {
    setLoading(true);
    setFetchError(null);
    const productNamesMap = new Map<string, number>();
    let from = 0;
    const limit = 1000;
    const to = limit - 1; // Supabase range is inclusive (0-999 for first 1000)
    let hasMore = true;

    try {
      while (hasMore) {
        const { data, error } = await supabase
          .from('daily_production')
          .select('product_name') // Only select product_name
          .range(from, from + to)
          .returns<DailyProductionItem[]>();

        if (error) {
          throw error;
        }

        if (data) {
          data.forEach(item => {
            if (item.product_name) {
              productNamesMap.set(item.product_name, (productNamesMap.get(item.product_name) || 0) + 1);
            }
          });
        }

        from += limit;
        hasMore = data !== null && data.length === limit;
      }

      const aggregatedItems: ProductCount[] = Array.from(productNamesMap.entries())
        .map(([name, count]) => ({ name, count }));

      aggregatedItems.sort((a, b) => a.name.localeCompare(b.name, 'pt-BR'));
      setItems(aggregatedItems);
    } catch (error: unknown) {
      setFetchError((error as Error).message || 'Erro ao carregar nomes de produtos.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (open) {
      fetchProductNames();
    } else {
      // Reset states when dialog closes
      setItems([]);
      setEditMap(new Map());
      setSavingSet(new Set());
      setSearch('');
      setFuseCandidate(null);
      setFetchError(null);
    }
  }, [open, fetchProductNames]);

  const filteredItems = useMemo(() => {
    if (!search) {
      return items;
    }
    const normalizedSearch = normalizeAndLowercase(search);
    return items.filter(item =>
      normalizeAndLowercase(item.name).includes(normalizedSearch)
    );
  }, [items, search, normalizeAndLowercase]);

  const handleEditChange = useCallback((oldName: string, newValue: string) => {
    setEditMap(prev => {
      const newMap = new Map(prev);
      newMap.set(oldName, newValue);
      return newMap;
    });
  }, []);

  const handleSave = useCallback(async (oldName: string, newNameInput: string, isMergeConfirmed: boolean = false) => {
    const trimmedNewName = newNameInput.trim();

    if (trimmedNewName === '' || trimmedNewName === oldName) {
      setEditMap(prev => {
        const newMap = new Map(prev);
        newMap.delete(oldName); // Clear input if no change or empty
        return newMap;
      });
      return;
    }

    setSavingSet(prev => new Set(prev).add(oldName));

    if (!isMergeConfirmed) {
      // Check for potential merge with an existing name (case/accent-insensitive)
      const existingItem = items.find(item =>
        item.name !== oldName && normalizeAndLowercase(item.name) === normalizeAndLowercase(trimmedNewName)
      );

      if (existingItem) {
        const oldItem = items.find(item => item.name === oldName);
        if (oldItem) {
          setFuseCandidate({
            nameA: oldName,
            nameB: existingItem.name,
            countA: oldItem.count,
            countB: existingItem.count,
          });
          setSavingSet(prev => { // Remove from saving state as we're waiting for confirmation
            const newSet = new Set(prev);
            newSet.delete(oldName);
            return newSet;
          });
          return;
        }
      }
    }

    try {
      const { error } = await supabase
        .from('daily_production')
        .update({ product_name: trimmedNewName })
        .eq('product_name', oldName);

      if (error) {
        throw error;
      }

      toast({
        title: isMergeConfirmed ? 'Itens fundidos' : 'Nome atualizado',
        description: isMergeConfirmed
          ? `Lançamentos de "${oldName}" fundidos em "${trimmedNewName}"`
          : `"${oldName}" renomeado para "${trimmedNewName}"`,
      });

      // Refetch and invalidate queries
      await fetchProductNames();
      queryClient.invalidateQueries({ queryKey: ['daily_production'] });
      queryClient.invalidateQueries({ queryKey: ['producao'] });

      setEditMap(prev => {
        const newMap = new Map(prev);
        newMap.delete(oldName); // Clear the edited state for this item
        return newMap;
      });

    } catch (error: unknown) {
      toast({
        title: 'Erro ao renomear',
        description: (error as Error).message || 'Tente novamente.',
        variant: 'destructive',
      });
    } finally {
      setSavingSet(prev => {
        const newSet = new Set(prev);
        newSet.delete(oldName);
        return newSet;
      });
      setFuseCandidate(null); // Clear any pending merge confirmation
    }
  }, [fetchProductNames, items, normalizeAndLowercase, queryClient]);

  const handleConfirmMerge = useCallback(() => {
    if (fuseCandidate) {
      // Call handleSave again with the confirmed flag
      handleSave(fuseCandidate.nameA, fuseCandidate.nameB, true);
    }
  }, [fuseCandidate, handleSave]);

  const handleCancelMerge = useCallback(() => {
    if (fuseCandidate) {
      // Reset the editMap entry for the name that triggered the merge
      setEditMap(prev => {
        const newMap = new Map(prev);
        newMap.delete(fuseCandidate.nameA);
        return newMap;
      });
    }
    setFuseCandidate(null);
  }, [fuseCandidate]);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button
          variant="outline"
          className="h-10 rounded-full border-[#57715B]/20 bg-[#E6DCCF]/40 px-3 text-[#57715B] hover:bg-[#57715B]/10 dark:border-white/10 dark:bg-white/10 dark:text-[#8FA893] transition-all hover:scale-105"
        >
          <Tags className="mr-2 h-4 w-4" />
          <span className="hidden sm:inline">Padronizar nomes</span>
          <span className="sr-only sm:hidden">Padronizar nomes</span>
        </Button>
      </DialogTrigger>
      <DialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle>Padronizar nomes de Produção Diária</DialogTitle>
          <DialogDescription>
            Edite o nome de um item e pressione Enter para salvar. Todos os lançamentos com aquele nome serão renomeados. O vínculo com o cadastro é preservado.
          </DialogDescription>
        </DialogHeader>

        <div className="flex items-center space-x-2 my-4">
          <Search className="h-4 w-4 text-[#57715B]/70" />
          <Input
            placeholder="Buscar nome..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
          />
        </div>

        {loading && (
          <div className="flex justify-center items-center h-48">
            <Loader2 className="h-8 w-8 animate-spin text-[#57715B]" />
          </div>
        )}

        {fetchError && (
          <div className="flex flex-col items-center justify-center h-48 text-red-500">
            <AlertCircle className="h-8 w-8 mb-2" />
            <p>{fetchError}</p>
            <Button onClick={fetchProductNames} className="mt-4">Tentar novamente</Button>
          </div>
        )}

        {!loading && !fetchError && items.length === 0 && (
          <div className="flex justify-center items-center h-48 text-gray-500 dark:text-gray-400">
            Nenhum nome de produto encontrado.
          </div>
        )}

        {!loading && !fetchError && filteredItems.length > 0 && (
          <div className="max-h-[70vh] overflow-y-auto pr-2">
            <div className="space-y-2">
              {filteredItems.map(item => {
                const currentName = editMap.has(item.name) ? editMap.get(item.name) : item.name;
                const isSaving = savingSet.has(item.name);

                return (
                  <div key={item.name} className="flex gap-2 items-center">
                    <Badge className="text-xs bg-[#57715B]/10 text-[#57715B] rounded-full px-2 py-0.5 whitespace-nowrap">
                      {item.count} lançamento(s)
                    </Badge>
                    <Input
                      value={currentName || ''} // Ensure value is always a string
                      onChange={(e) => handleEditChange(item.name, e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' && !isSaving) {
                          void handleSave(item.name, currentName || ''); // Use void for async calls in event handlers
                        }
                      }}
                      className="flex-grow bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
                      disabled={isSaving}
                    />
                    <Button
                      onClick={() => void handleSave(item.name, currentName || '')} // Use void
                      disabled={isSaving}
                      className="h-8 w-8 rounded-full bg-[#57715B]/10 hover:bg-[#57715B]/20 text-[#57715B] p-0 flex-shrink-0"
                    >
                      {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
                    </Button>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </DialogContent>

      <AlertDialog open={!!fuseCandidate} onOpenChange={(openState) => !openState && handleCancelMerge()}>
        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle>Confirmação de Fusão</AlertDialogTitle>
            <AlertDialogDescription>
              Já existe um item chamado &quot;{fuseCandidate?.nameB}&quot; ({fuseCandidate?.countB} lançamentos).
              Os {fuseCandidate?.countA} lançamentos de &quot;{fuseCandidate?.nameA}&quot; serão fundidos com &quot;{fuseCandidate?.nameB}&quot;
              e passarão a contar como um único item. O histórico e vínculo são preservados.
              Deseja continuar?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10">Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={handleConfirmMerge} className="bg-red-600 hover:bg-red-700 text-white">Fundir</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Dialog>
  );
}

