      <DialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl sm:max-w-2xl">
        <DialogHeader>
          <DialogTitle className="text-[#57715B] dark:text-[#E6DCCF]">
            Padronizar nomes de Produção Diária
          </DialogTitle>
          <DialogDescription>
            Edite o nome de um item e pressione Enter para salvar. Todos os lançamentos
            com aquele nome serão renomeados. O vínculo com o cadastro é preservado.
          </DialogDescription>
        </DialogHeader>

        <div className="flex items-center gap-2 my-3">
          <Search className="h-4 w-4 flex-shrink-0 text-[#57715B]/70" />
          <Input
            placeholder="Buscar nome..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl"
          />
        </div>

        {loading && (
          <div className="flex justify-center items-center h-48">
            <Loader2 className="h-8 w-8 animate-spin text-[#57715B]" />
          </div>
        )}

        {fetchError && (
          <div className="flex flex-col items-center justify-center h-48 gap-3 text-red-600">
            <AlertCircle className="h-8 w-8" />
            <p className="text-sm text-center">{fetchError}</p>
            <Button
              onClick={() => void fetchProductNames()}
              className="bg-[#57715B] text-white hover:bg-[#465b49]"
            >
              Tentar novamente
            </Button>
          </div>
        )}

        {!loading && !fetchError && items.length === 0 && (
          <div className="flex justify-center items-center h-48 text-muted-foreground text-sm">
            Nenhum item lançado ainda.
          </div>
        )}

        {!loading && !fetchError && filteredItems.length > 0 && (
          <div className="max-h-[70vh] overflow-y-auto pr-1">
            <div className="space-y-2">
              {filteredItems.map((item) => {
                const currentName = editMap.has(item.name)
                  ? (editMap.get(item.name) ?? item.name)
                  : item.name;
                const isSaving = savingSet.has(item.name);

                return (
                  <div key={item.name} className="flex gap-2 items-center">
                    <Badge className="text-xs bg-[#57715B]/10 text-[#57715B] rounded-full px-2 py-0.5 whitespace-nowrap border-0 hover:bg-[#57715B]/10">
                      {item.count} lanç.
                    </Badge>
                    <Input
                      value={currentName}
                      onChange={(e) => handleEditChange(item.name, e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' && !isSaving) {
                          void handleSave(item.name, currentName);
                        }
                      }}
                      className="flex-1 bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus-visible:ring-[#57715B]/30 rounded-xl text-sm"
                      disabled={isSaving}
                    />
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => void handleSave(item.name, currentName)}
                      disabled={isSaving}
                      className="h-8 w-8 rounded-full bg-[#57715B]/10 hover:bg-[#57715B]/20 text-[#57715B] flex-shrink-0"
                    >
                      {isSaving ? (
                        <Loader2 className="h-4 w-4 animate-spin" />
                      ) : (
                        <Check className="h-4 w-4" />
                      )}
                    </Button>
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </DialogContent>

      <AlertDialog
        open={!!fuseCandidate}
        onOpenChange={(isOpen) => {
          if (!isOpen) handleCancelMerge();
        }}
      >
        <AlertDialogContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
          <AlertDialogHeader>
            <AlertDialogTitle>Confirmar fusão de itens</AlertDialogTitle>
            <AlertDialogDescription>
              Já existe um item chamado &ldquo;{fuseCandidate?.nameB}&rdquo; (
              {fuseCandidate?.countB} lançamento(s)). Os {fuseCandidate?.countA}{' '}
              lançamento(s) de &ldquo;{fuseCandidate?.nameA}&rdquo; serão{' '}
              <strong>fundidos</strong> com &ldquo;{fuseCandidate?.nameB}&rdquo; e
              passarão a contar como um único item. O histórico e vínculo são
              preservados. Deseja continuar?
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel
              className="border-[#57715B]/20 text-[#57715B] hover:bg-[#57715B]/10"
              onClick={handleCancelMerge}
            >
              Cancelar
            </AlertDialogCancel>
            <AlertDialogAction
              className="bg-red-600 hover:bg-red-700 text-white"
              onClick={handleConfirmMerge}
            >
              Fundir
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Dialog>
  );
}

