          <div className="relative overflow-hidden rounded-[2.5rem] p-1 bg-white/60 dark:bg-black/20 backdrop-blur-xl saturate-150 border border-white/50 dark:border-white/10 shadow-[0_8px_32px_-8px_rgba(0,0,0,0.05)] transition-all duration-300">
